'use strict';

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function escapeHtml(value) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function renderInfoPanel(model, theme) {
  const color = /^#[0-9a-fA-F]{6}$/;
  if (
    !isRecord(model) || typeof model.heading !== 'string' ||
    !Array.isArray(model.paragraphs) || !model.paragraphs.every((p) => typeof p === 'string') ||
    !isRecord(theme) || !color.test(theme.background) || !color.test(theme.text) ||
    !Number.isInteger(theme.padding) || theme.padding < 0 || theme.padding > 1000
  ) {
    throw new TypeError('Invalid panel input');
  }

  const paragraphs = model.paragraphs.map((p) => '<p>' + escapeHtml(p) + '</p>').join('');
  return '<section style="background:' + theme.background + ';padding:' + theme.padding +
    'px"><h2 style="color:' + theme.text + '">' + model.heading +
    '</h2>' + paragraphs + '</section>';
}

module.exports = { renderInfoPanel };

