'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['renderInfoPanel']);
const { renderInfoPanel } = api;

const model = { heading: 'A & <B> "C"', paragraphs: ['one & two', '<tag>', '', '"quoted"'] };
const theme = { background: '#12abEF', text: '#000000', padding: 1000 };
const modelBefore = { heading: model.heading, paragraphs: model.paragraphs.slice() };
const themeBefore = { ...theme };
assert.strictEqual(
  renderInfoPanel(model, theme),
  '<section style="background:#12abEF;padding:1000px"><h2 style="color:#000000">A &amp; &lt;B&gt; &quot;C&quot;</h2><p>one &amp; two</p><p>&lt;tag&gt;</p><p></p><p>&quot;quoted&quot;</p></section>'
);
assert.deepStrictEqual(model, modelBefore);
assert.deepStrictEqual(theme, themeBefore);
assert.strictEqual(renderInfoPanel({ heading: '', paragraphs: [] }, { background: '#ffffff', text: '#ABC123', padding: 0 }), '<section style="background:#ffffff;padding:0px"><h2 style="color:#ABC123"></h2></section>');
assert.strictEqual(renderInfoPanel({ heading: '&lt;', paragraphs: ['&amp;'] }, { background: '#123456', text: '#abcdef', padding: 1 }), '<section style="background:#123456;padding:1px"><h2 style="color:#abcdef">&amp;lt;</h2><p>&amp;amp;</p></section>');
for (const badModel of [null, [], {}, { heading: 1, paragraphs: [] }, { heading: 'x', paragraphs: null }, { heading: 'x', paragraphs: ['ok', 1] }]) {
  assert.throws(() => renderInfoPanel(badModel, { background: '#ffffff', text: '#000000', padding: 0 }), TypeError);
}
for (const badTheme of [null, [], {}, { background: 'ffffff', text: '#000000', padding: 0 }, { background: '#fffff', text: '#000000', padding: 0 }, { background: '#gggggg', text: '#000000', padding: 0 }, { background: '#ffffff', text: '#00000g', padding: 0 }, { background: '#ffffff', text: '#000000', padding: -1 }, { background: '#ffffff', text: '#000000', padding: 1001 }, { background: '#ffffff', text: '#000000', padding: 1.5 }]) {
  assert.throws(() => renderInfoPanel({ heading: 'x', paragraphs: [] }, badTheme), TypeError);
}

